func:
// Conecta la nube al broker y se suscribe a lo que publican paradas y autobuses.
// El prefijo sale de la variable de entorno global TOPIC_PREFIX.
const P = env.get("TOPIC_PREFIX");
const temas = ["parada/+/solicitud", "parada/+/deteccion", "autobus/+/evento"];
node.send([{ action: "connect", broker: {
    broker: env.get("MQTT_BROKER"), port: Number(env.get("MQTT_PORT")),
    clientid: "", cleansession: true, force: true
} }, null]);
node.send([{ action: "subscribe", topic: temas.map(t => ({ topic: `${P}/${t}`, qos: 1 })) }, null]);
node.send([null, { origen: "arranque" }]);
node.status({ fill: "blue", shape: "ring", text: `${P}/... (${temas.length} suscripciones)` });
return null;

// HORARIOS PRECARGADOS (supuesto S3).
// Cada escenario fija línea, parada, autobús y minuto de paso.
// t_min son minutos desde que se carga el escenario, para poder repetir la prueba.
const ESCENARIOS = {
    E1: {
        id: "E1",
        descripcion: "Un C15 a los 4 min y un L9 a los 12",
        pasos: [
            { linea: "C15", parada: "P101", bus: "AUT312", t_min: 4 },
            { linea: "L9",  parada: "P101", bus: "AUT205", t_min: 12 }
        ]
    },
    E2: {
        id: "E2",
        descripcion: "Sin autobuses en los próximos 20 min: el primero pasa a los 26",
        pasos: [
            { linea: "C15", parada: "P101", bus: "AUT312", t_min: 26 }
        ]
    }
};

if (msg.payload === "limpiar") return { origen: "limpiar" };   // botón del panel
const e = ESCENARIOS[msg.payload];
if (!e) { node.warn(`Escenario desconocido: ${msg.payload}`); return null; }
node.status({ fill: "green", shape: "dot", text: `${e.id}: ${e.descripcion}` });
return { origen: "escenario", payload: e };

// GESTOR DE SOLICITUDES (lógica de nube, diseño base).
// Una solicitud por parada y un autobús avisado por solicitud.
// Estados: asignada -> en_parada -> cerrada.
// Salida 1: MQTT. Salida 2: trazas. Salidas 3 y 4: reloj y siguiente autobús para el panel.
const P = env.get("TOPIC_PREFIX");
const F = Number(env.get("FACTOR_TIEMPO")) || 1;

// Tiempos del diseño en segundos. El reloj simulado avanza F veces más rápido.
const T = { proximos: 20 * 60, margen: 30, renovar: 30 };

const ahora = Date.now();
const mqtt = [], trazas = [];

let st = flow.get("nube");
if (!st || msg.origen === "arranque") st = { escenario: null, t0: 0, solicitudes: {}, ultimoProximos: -1e9 };

function pub(tema, payload, retain) { mqtt.push({ topic: `${P}/${tema}`, payload: payload, qos: 1, retain: !!retain }); }
function traza(texto) { trazas.push({ payload: texto }); }
function simS() { return st.escenario ? (ahora - st.t0) * F / 1000 : 0; }
function eta(paso) { return paso.t_min * 60 - simS(); }
function pasosDe(parada) { return st.escenario ? st.escenario.pasos.filter(p => p.parada === parada) : []; }
function paradas() { return st.escenario ? [...new Set(st.escenario.pasos.map(p => p.parada))] : []; }
function aviso(s, tipo) { pub(`parada/${s.parada}/aviso`, { tipo: tipo, linea: s.linea, solicitud: s.id }); }
function orden(s, tipo) { pub(`autobus/${s.bus}/orden`, { tipo: tipo, solicitud: s.id }); }

function publicarProximos(parada) {
    const buses = pasosDe(parada)
        .map(p => ({ linea: p.linea, eta: eta(p) }))
        .filter(x => x.eta > 0 && x.eta <= T.proximos)
        .sort((a, b) => a.eta - b.eta)
        .map(x => ({ linea: x.linea, min: Math.ceil(x.eta / 60) }));
    pub(`parada/${parada}/proximos`, { ts: Math.floor(ahora / 1000), buses: buses }, true);
}
// Cierre: orden fin al autobús, asignación borrada y aviso a la parada
function cerrar(s, motivo) {
    orden(s, "fin");
    pub(`autobus/${s.bus}/asistencia`, "", true);
    aviso(s, "cerrada");
    delete st.solicitudes[s.parada];
    traza(`Solicitud ${s.id} (${s.linea}, ${s.bus}): ${s.estado} -> cerrada (${motivo})`);
}

if (msg.origen === "arranque") {
    traza(`Nube arrancada. Prefijo ${P}, factor de tiempo ${F}`);
} else if (msg.origen === "escenario" || msg.origen === "limpiar") {
    for (const s of Object.values(st.solicitudes)) cerrar(s, "cambio de escenario");
    const viejo = st.escenario;
    st.escenario = msg.origen === "escenario" ? msg.payload : null;
    st.t0 = ahora;
    st.ultimoProximos = 0;
    // La nube empieza sin solicitudes: se borran las asignaciones retenidas que pudieran quedar
    const buses = new Set([].concat(viejo ? viejo.pasos : [], st.escenario ? st.escenario.pasos : []).map(p => p.bus));
    buses.forEach(b => pub(`autobus/${b}/asistencia`, "", true));
    if (st.escenario) {
        paradas().forEach(publicarProximos);
        traza(`Escenario ${st.escenario.id} cargado: ${st.escenario.descripcion}`);
    } else {
        if (viejo) [...new Set(viejo.pasos.map(p => p.parada))].forEach(p => pub(`parada/${p}/proximos`, "", true));
        traza("Escenario descargado y retenidos limpiados");
    }
} else if (msg.origen === "tick") {
    if (st.escenario) {
        if (simS() - st.ultimoProximos >= T.renovar) {
            st.ultimoProximos = simS();
            paradas().forEach(publicarProximos);
        }
        // Salvaguarda: al autobús avisado se le pasó su margen sin que el ultrasonidos lo viera
        for (const s of Object.values(st.solicitudes)) {
            if (s.estado === "asignada" && s.t - simS() < -T.margen) cerrar(s, "autobús no detectado");
        }
    }
} else if (typeof msg.topic === "string" && msg.topic.startsWith(P + "/")) {
    const [clase, id, tema] = msg.topic.slice(P.length + 1).split("/");
    const m = msg.payload;
    const valido = m && typeof m === "object";
    const s = clase === "parada" ? st.solicitudes[id] : Object.values(st.solicitudes).find(x => x.bus === id);

    if (clase === "parada" && tema === "solicitud" && valido && m.solicitud && m.linea) {
        if (s) {
            traza(`${id}: ya hay una solicitud activa, se ignora la nueva`);
        } else {
            // Se avisa al siguiente autobús de la línea elegida
            const paso = pasosDe(id).filter(p => p.linea === m.linea && eta(p) > 0).sort((a, b) => a.t_min - b.t_min)[0];
            const nueva = { id: m.solicitud, parada: id, linea: m.linea,
                asistencia: m.asistencia === "movilidad" ? "movilidad" : "visual",
                bus: paso ? paso.bus : null, t: paso ? paso.t_min * 60 : 0, estado: "asignada" };
            if (!paso) {
                aviso(nueva, "cerrada");
                traza(`Solicitud ${nueva.id}: no quedan autobuses de la línea ${nueva.linea}`);
            } else {
                st.solicitudes[id] = nueva;
                pub(`autobus/${nueva.bus}/asistencia`, { solicitud: nueva.id, parada: id, linea: nueva.linea, asistencia: nueva.asistencia }, true);
                aviso(nueva, "asignado");
                traza(`Solicitud ${nueva.id}: ${nueva.linea}, ${nueva.asistencia}. Avisado ${nueva.bus} (llega en ${Math.round(eta(paso))} s)`);
            }
        }
    } else if (clase === "parada" && tema === "deteccion" && valido) {
        if (m.estado === "detenido" && s && s.estado === "asignada") {
            // Doble verificación: vehículo detenido y, según los horarios, al autobús avisado le toca llegar
            const e = s.t - simS();
            if (e > -T.margen && e <= T.margen) {
                s.estado = "en_parada";
                aviso(s, "llegado");
                orden(s, s.asistencia === "movilidad" ? "rampa" : "guiar");
                traza(`Solicitud ${s.id}: asignada -> en_parada (${s.bus}, ${m.distancia_cm} cm)`);
            } else {
                traza(`${id}: vehículo detenido fuera del margen de ${s.bus}, se ignora`);
            }
        } else if (m.estado === "libre" && s && s.estado === "en_parada") {
            cerrar(s, "el autobús se va");   // la solicitud termina aunque el conductor no pulse
        }
    } else if (clase === "autobus" && tema === "evento" && valido && m.tipo === "recogido") {
        if (s && s.id === m.solicitud && s.estado === "en_parada") cerrar(s, "pulsador del conductor");
        else traza(`${id}: recogido ignorado, ese autobús no está en la parada`);
    }
}

flow.set("nube", st);

// Estado del nodo y reloj para el panel
let panelReloj = "sin escenario cargado", panelSiguiente = "ninguno";
if (st.escenario) {
    const t = simS();
    const mmss = x => `${Math.floor(x / 60)}:${String(Math.floor(x % 60)).padStart(2, "0")}`;
    const sig = st.escenario.pasos.map(p => ({ p: p, e: eta(p) })).filter(x => x.e > -T.margen).sort((a, b) => a.e - b.e)[0];
    panelReloj = `${st.escenario.id}, minuto ${mmss(t)}${F !== 1 ? " (tiempo x" + F + ")" : ""}`;
    if (sig) panelSiguiente = sig.e > T.margen ? `${sig.p.linea} ${sig.p.bus} pasa en ${Math.round(sig.e / F)} s` : `${sig.p.linea} ${sig.p.bus} está pasando ahora`;
    const sols = Object.values(st.solicitudes).map(s => `${s.parada} ${s.linea} ${s.estado}`);
    node.status({ fill: sols.length ? "green" : "blue", shape: "dot", text: `${panelReloj} | ${panelSiguiente}${sols.length ? " | " + sols.join(", ") : ""}` });
} else {
    node.status({ fill: "grey", shape: "ring", text: "sin escenario cargado" });
}
const previo = context.get("panel") || {};
const salReloj = previo.reloj !== panelReloj ? { payload: panelReloj } : null;
const salSiguiente = previo.siguiente !== panelSiguiente ? { payload: panelSiguiente } : null;
context.set("panel", { reloj: panelReloj, siguiente: panelSiguiente });

return [mqtt, trazas, salReloj, salSiguiente];

// Conecta la parada al broker y se suscribe a sus topics.
// Salida 1: acciones para el mqtt in de avisos. Salida 2: acciones para el mqtt in
// del escáner BLE simulado. Salida 3: arranque del firmware.
const P = env.get("TOPIC_PREFIX");
const ID = env.get("PARADA_ID");
node.send([{ action: "connect", broker: {
    broker: env.get("MQTT_BROKER"), port: Number(env.get("MQTT_PORT")),
    clientid: "", cleansession: true, force: true
} }, null, null]);
node.send([{ action: "subscribe", topic: [
    { topic: `${P}/parada/${ID}/aviso`, qos: 1 },
    { topic: `${P}/parada/${ID}/proximos`, qos: 1 }
] }, null, null]);
// "El aire" alrededor de la parada: sustituye a la radio BLE mientras no hay hardware
node.send([null, { action: "subscribe", topic: [{ topic: `${P}/sim/ble/${ID}`, qos: 0 }] }, null]);
node.send([null, null, { origen: "arranque" }]);
node.status({ fill: "blue", shape: "ring", text: `${P}/parada/${ID}/...` });
return null;

// ROTARY ENCODER KY-040 (virtual, n.º 37 del kit).
// Entrega lo mismo que el driver del encoder real: un giro de un paso (+1 o -1)
// o una pulsación del eje.
let pos = context.get("pos") || 0;
let salida;
if (msg.payload === "pulsar") {
    salida = { pulsado: true };
    node.status({ fill: "green", shape: "dot", text: `pulsado (posición ${pos})` });
} else {
    const giro = Number(msg.payload) < 0 ? -1 : 1;
    pos += giro;
    context.set("pos", pos);
    salida = { giro: giro, posicion: pos };
    node.status({ fill: "blue", shape: "dot", text: `giro ${giro > 0 ? "+1" : "-1"} (posición ${pos})` });
}
return { origen: "encoder", payload: salida };

// ULTRASONIDOS HC-SR04 (virtual, n.º 46 del kit).
// Con cada muestreo entrega una distancia en cm, como el sensor real.
// Los inject "Vehículo se detiene" y "Vehículo se va" cambian lo que hay delante.
if (msg.topic === "mundo") {
    context.set("vehiculo", msg.payload === "detenido");
    return null;
}
const vehiculo = context.get("vehiculo") || false;
// Vehículo parado a unos 60 cm. Calzada vacía: cerca del alcance máximo (400 cm)
const base = vehiculo ? 60 : 395;
const cm = Math.round((base + (Math.random() - 0.5) * 8) * 10) / 10;
node.status({ fill: vehiculo ? "green" : "grey", shape: vehiculo ? "dot" : "ring",
    text: `${cm} cm (${vehiculo ? "vehículo delante" : "calzada libre"})` });
return { origen: "ultrasonidos", payload: { distancia_cm: cm } };

// FIRMWARE DE LA PARADA (lo que hará la Raspberry Pi, diseño base).
// Entradas: encoder, ultrasonidos, anuncios BLE, avisos y próximos por MQTT, y un tick.
// Salida 1: MQTT. Salida 2: altavoz (texto que se diría por voz). Salida 3: trazas.
const P = env.get("TOPIC_PREFIX");
const F = Number(env.get("FACTOR_TIEMPO")) || 1;
const ID = env.get("PARADA_ID");
const UMBRAL_CM = Number(env.get("UMBRAL_CM")) || 150;            // por debajo hay un vehículo
const T_DETENCION_MS = Number(env.get("T_DETENCION_MS")) || 1000; // tiempo seguido para darlo por detenido
const T = { ausencia: 120, proximosCaduca: 60 };                  // segundos del diseño, se dividen por F

const ahora = Date.now();
const mqtt = [], voz = [], trazas = [];

let st = flow.get("parada");
if (!st || msg.origen === "arranque") {
    st = { usuario: null, proximos: null, menu: -1, menuLinea: null, solicitud: null,
        us: { cerca: false, desde: 0, publicado: false } };
}
function pub(tema, payload) { mqtt.push({ topic: `${P}/parada/${ID}/${tema}`, payload: payload, qos: 1, retain: false }); }
function decir(texto) { voz.push({ payload: texto }); }
function traza(texto) { trazas.push({ payload: texto }); }

function enMinutos(mins) {
    const partes = mins.map(m => `en ${m}`);
    const lista = partes.length > 1 ? `${partes.slice(0, -1).join(", ")} y ${partes[partes.length - 1]}` : partes[0];
    return `${lista} ${mins.length === 1 && mins[0] === 1 ? "minuto" : "minutos"}`;
}
// Opciones del menú: una por línea. Devuelve null si no hay una lista reciente de la nube.
function opciones() {
    if (!st.proximos || ahora / 1000 - st.proximos.ts > T.proximosCaduca / F + 3) return null;
    const ops = [];
    for (const b of st.proximos.buses) {
        let o = ops.find(x => x.linea === b.linea);
        if (!o) { o = { linea: b.linea, mins: [] }; ops.push(o); }
        o.mins.push(b.min);
    }
    return ops;
}
function anunciar() {
    const ops = opciones();
    st.menu = -1; st.menuLinea = null;
    if (ops === null) return decir("No hay información de autobuses en este momento.");
    if (!ops.length) return decir("No hay autobuses en los próximos 20 minutos.");
    decir(`Próximos autobuses: ${ops.map(o => `línea ${o.linea} ${enMinutos(o.mins)}`).join("; ")}. ` +
        "Gire el mando para elegir línea y púlselo para solicitarla.");
}

const base = `${P}/parada/${ID}/`;
if (msg.origen === "arranque") {
    traza(`Parada ${ID} arrancada`);
} else if (msg.origen === "tick") {
    // Más de 2 minutos sin baliza: la parada olvida al usuario, para anunciar de nuevo al siguiente
    if (st.usuario && ahora - st.usuario.ultima > T.ausencia * 1000 / F) {
        traza("Más de 2 min sin baliza: la parada queda libre para otro usuario");
        st.usuario = null; st.menu = -1; st.menuLinea = null;
    }
} else if (msg.topic === `${P}/sim/ble/${ID}`) {
    // Anuncio BLE de 4 bytes: versión, tipo de asistencia e id
    const b = msg.payload;
    if (!Buffer.isBuffer(b) || b.length !== 4 || b[0] !== 1 || (b[1] !== 1 && b[1] !== 2)) {
        traza("Anuncio BLE descartado: no tiene el formato de la baliza");
    } else if (!st.usuario) {
        // La primera baliza da al usuario por presente, sin umbral de señal (S5)
        st.usuario = { asistencia: b[1] === 1 ? "visual" : "movilidad", ultima: ahora };
        traza(`Baliza recibida (${st.usuario.asistencia}): usuario presente`);
        anunciar();
    } else {
        st.usuario.ultima = ahora;
    }
} else if (msg.origen === "encoder") {
    const e = msg.payload;
    if (!st.usuario) {
        traza("Encoder ignorado: no hay ningún usuario presente");
    } else if (e.giro) {
        const ops = opciones();
        if (ops === null) decir("No hay información de autobuses en este momento.");
        else if (!ops.length) decir("No hay autobuses en los próximos 20 minutos.");
        else {
            const n = ops.length;
            st.menu = st.menu < 0 ? (e.giro > 0 ? 0 : n - 1) : (((st.menu + e.giro) % n) + n) % n;
            st.menuLinea = ops[st.menu].linea;
            decir(`Línea ${ops[st.menu].linea}, ${enMinutos(ops[st.menu].mins)}.`);
        }
    } else if (e.pulsado) {
        if (st.solicitud) decir(`Ya tiene solicitada la línea ${st.solicitud.linea}.`);
        else if (st.menuLinea === null) anunciar();   // sin línea elegida: repite la lista
        else {
            const id = "S-" + Math.floor(Math.random() * 0x10000).toString(16).padStart(4, "0");
            st.solicitud = { id: id, linea: st.menuLinea, estado: "enviada" };
            pub("solicitud", { solicitud: id, linea: st.menuLinea, asistencia: st.usuario.asistencia });
            decir(`Solicitando línea ${st.menuLinea}.`);
            st.menu = -1; st.menuLinea = null;
        }
    }
} else if (msg.origen === "ultrasonidos") {
    const cm = msg.payload.distancia_cm;
    const cerca = cm < UMBRAL_CM;
    if (cerca !== st.us.cerca) { st.us.cerca = cerca; st.us.desde = ahora; }
    if (cerca !== st.us.publicado && ahora - st.us.desde >= T_DETENCION_MS) {
        st.us.publicado = cerca;
        pub("deteccion", { estado: cerca ? "detenido" : "libre", distancia_cm: Math.round(cm) });
        traza(`Ultrasonidos: ${Math.round(cm)} cm, vehículo ${cerca ? "detenido" : "fuera"}`);
    }
} else if (msg.topic === base + "proximos") {
    const p = msg.payload;
    st.proximos = (p && typeof p === "object" && Array.isArray(p.buses)) ? { ts: p.ts, buses: p.buses } : null;
} else if (msg.topic === base + "aviso") {
    const a = msg.payload;
    if (a && typeof a === "object" && st.solicitud && a.solicitud === st.solicitud.id) {
        if (a.tipo === "asignado") { st.solicitud.estado = "asignada"; decir(`Línea ${a.linea} avisada.`); }
        else if (a.tipo === "llegado") { st.solicitud.estado = "en parada"; decir(`Su autobús de la línea ${a.linea} ha llegado.`); }
        else if (a.tipo === "cerrada") { st.solicitud = null; traza(`Solicitud ${a.solicitud} cerrada`); }
    }
}

flow.set("parada", st);
const partes = [st.usuario ? `usuario presente (${st.usuario.asistencia})` : "sin usuario"];
if (st.solicitud) partes.push(`solicitud ${st.solicitud.linea}: ${st.solicitud.estado}`);
if (st.us.publicado) partes.push("vehículo detenido");
node.status({ fill: st.usuario ? "green" : "grey", shape: st.usuario ? "dot" : "ring", text: partes.join(" | ") });
return [mqtt, voz, trazas];

// TIEMPO -> AVISO DE SUELO MOJADO POR EL ALTAVOZ
// Entrada: salida del nodo openweathermap
//   msg.payload -> datos resumidos (weather, detail, tempc...)
//   msg.data    -> respuesta completa de la API
// Salida: msg.payload con la frase para el altavoz.
// Solo habla si hay un usuario en la parada y una vez por usuario,
// para no repetir el aviso en cada consulta a la API.

const datos = msg.data || {};
const resumen = msg.payload || {};

// Código de condición de OpenWeatherMap: 2xx tormenta, 3xx llovizna, 5xx lluvia, 6xx nieve
const codigo = (datos.weather && datos.weather[0] && datos.weather[0].id) || 0;
const grupo = Math.floor(codigo / 100);
// Lluvia acumulada (mm) en la última hora o en las últimas 3 horas
const lluviaMm = (datos.rain && (datos.rain["1h"] || datos.rain["3h"])) || 0;
const temp = resumen.tempc;

let aviso = null;
if (grupo === 6) aviso = "Atención: está nevando, el suelo puede estar resbaladizo.";
else if (grupo === 2) aviso = "Atención: hay tormenta, el suelo está mojado. Tenga cuidado al subir al autobús.";
else if (grupo === 5 || grupo === 3) aviso = "Atención: está lloviendo, el suelo puede estar resbaladizo. Tenga cuidado al subir al autobús.";
else if (lluviaMm > 0) aviso = "Atención: ha llovido recientemente, el suelo puede estar mojado.";

// Suelo mojado y temperatura bajo cero: posible hielo
if (aviso && typeof temp === "number" && temp <= 0) aviso += " Puede haber hielo.";

flow.set("avisoSuelo", aviso);

// Estado de la parada que mantiene el nodo "Firmware parada"
const parada = flow.get("parada");
const hayUsuario = !!(parada && parada.usuario);
if (!hayUsuario) flow.set("avisoSueloDicho", false);   // el siguiente usuario lo volverá a oír

node.status(aviso
    ? { fill: "blue", shape: "dot", text: `suelo mojado (${resumen.detail || codigo})` }
    : { fill: "green", shape: "dot", text: `suelo seco (${resumen.detail || codigo})` });

if (!aviso || !hayUsuario || flow.get("avisoSueloDicho")) return null;

flow.set("avisoSueloDicho", true);
msg.payload = aviso;
return msg;

// Conecta el autobús al broker y se suscribe a su asignación y a sus órdenes.
// BUS_ID es una variable de entorno de la pestaña.
const P = env.get("TOPIC_PREFIX");
const B = env.get("BUS_ID");
node.send([{ action: "connect", broker: {
    broker: env.get("MQTT_BROKER"), port: Number(env.get("MQTT_PORT")),
    clientid: "", cleansession: true, force: true
} }, null]);
node.send([{ action: "subscribe", topic: [
    { topic: `${P}/autobus/${B}/asistencia`, qos: 1 },
    { topic: `${P}/autobus/${B}/orden`, qos: 1 }
] }, null]);
node.send([null, { origen: "arranque" }]);
node.status({ fill: "blue", shape: "ring", text: `${P}/autobus/${B}/...` });
return null;

// PULSADOR DEL CONDUCTOR (virtual, Digital Push Button n.º 7 del kit).
// Entrega una pulsación, como el botón real ya sin rebotes.
const n = (context.get("n") || 0) + 1;
context.set("n", n);
node.status({ fill: "green", shape: "dot", text: `pulsado (${n})` });
return { origen: "pulsador", payload: { pulsado: true } };

// FIRMWARE DEL AUTOBÚS (lo que hará el ESP32, diseño base).
// Entradas: asignación y órdenes por MQTT, y el pulsador del conductor.
// Salidas: 1 MQTT, 2 LCD 8x2, 3 zumbador, 4 servo de la rampa, 5 trazas.
const P = env.get("TOPIC_PREFIX");
const B = env.get("BUS_ID");
const mqtt = [], trazas = [];
const arranque = msg.origen === "arranque";

let st = flow.get("bus");
if (!st || arranque) st = { asistencia: null, enServicio: false, zumbador: false, rampa: false, lcd: "" };
const antes = { zumbador: st.zumbador, rampa: st.rampa, lcd: st.lcd };
function traza(texto) { trazas.push({ payload: `${B}: ${texto}` }); }
function parar() { st.zumbador = false; st.rampa = false; st.enServicio = false; }

const base = `${P}/autobus/${B}/`;
if (arranque) {
    traza("arrancado");
} else if (msg.origen === "pulsador") {
    // El conductor confirma que la persona ha subido
    if (st.enServicio && st.asistencia) {
        const solicitud = st.asistencia.solicitud;
        parar();
        mqtt.push({ topic: base + "evento", payload: { tipo: "recogido", solicitud: solicitud }, qos: 1, retain: false });
        traza(`pulsador: recogida confirmada (${solicitud})`);
    } else {
        traza("pulsador ignorado: no hay ningún servicio en curso");
    }
} else if (msg.topic === base + "asistencia") {
    const p = msg.payload;
    if (p && typeof p === "object" && !Buffer.isBuffer(p) && p.solicitud) {
        st.asistencia = p;
        traza(`asignación: ${p.parada} ${p.linea}, ${p.asistencia}`);
    } else {
        // Retenido borrado: ya no hay solicitud
        if (st.asistencia) traza("asignación retirada");
        st.asistencia = null;
        parar();
    }
} else if (msg.topic === base + "orden") {
    const o = msg.payload;
    // Solo se obedecen las órdenes de la solicitud asignada
    if (o && typeof o === "object" && st.asistencia && o.solicitud === st.asistencia.solicitud) {
        if (o.tipo === "guiar") { st.zumbador = true; st.enServicio = true; }
        else if (o.tipo === "rampa") { st.rampa = true; st.enServicio = true; }
        else if (o.tipo === "fin") parar();
        traza(`orden ${o.tipo} (${o.solicitud})`);
    }
}

// LCD 0802: 2 líneas de 8 caracteres
if (st.asistencia) {
    const l1 = `${st.asistencia.parada} ${st.asistencia.linea}`.slice(0, 8).padEnd(8);
    const l2 = (st.asistencia.asistencia === "movilidad" ? "RAMPA" : "VISUAL").padEnd(8);
    st.lcd = `[${l1}][${l2}]`;
} else {
    st.lcd = "[        ][        ]";
}
flow.set("bus", st);

const salLcd = (arranque || st.lcd !== antes.lcd) ? { payload: st.lcd } : null;
const salZum = (arranque || st.zumbador !== antes.zumbador) ? { payload: st.zumbador ? "SONANDO" : "apagado" } : null;
const salServo = (arranque || st.rampa !== antes.rampa) ? { payload: st.rampa ? "90 grados, rampa desplegada" : "0 grados, rampa recogida" } : null;
node.status({ fill: st.enServicio ? "green" : (st.asistencia ? "yellow" : "grey"), shape: st.asistencia ? "dot" : "ring",
    text: st.asistencia ? `${st.asistencia.parada} ${st.asistencia.linea}${st.enServicio ? " | en servicio" : ""}` : "sin asignación" });
return [mqtt, salLcd, salZum, salServo, trazas];

// Conexión que hace de "aire" para la baliza BLE mientras no hay radio real.
// Sin LWT: una baliza no se conecta a nada, solo emite.
node.send([{ action: "connect", broker: {
    broker: env.get("MQTT_BROKER"), port: Number(env.get("MQTT_PORT")),
    clientid: "", cleansession: true, force: true
} }, null]);
node.send([null, { origen: "arranque" }]);
return null;

// DISPOSITIVO DE USUARIO (ESP32 virtual en el bastón o en la silla).
// Emite un anuncio BLE de 4 bytes cada 10 s, siempre (S5). No escucha nada.
// "Llega" y "se va" solo deciden si la parada está al alcance de la radio.
// Salida 1: anuncio hacia el aire simulado. Salida 2: trazas.
const P = env.get("TOPIC_PREFIX");
const F = Number(env.get("FACTOR_TIEMPO")) || 1;
const ID = Number(env.get("DISPOSITIVO_ID")) || 7;   // 0x0007 es D07
const PARADA = env.get("PARADA_CERCANA");
const PERIODO_MS = 10000 / F;

let st = context.get("st");
if (!st || msg.origen === "arranque") st = { enParada: false, tipo: 1, ultima: 0, n: 0 };
const ahora = Date.now();
let anuncio = null, traza = null;
const origen = msg.origen || msg.topic;   // inject (origen) o botón del panel (topic)

if (origen === "llega") {
    st.enParada = true;
    st.tipo = msg.payload === "movilidad" ? 2 : 1;   // 1 visual (bastón), 2 movilidad (silla)
    traza = { payload: `D${String(ID).padStart(2, "0")} llega a ${PARADA} (${st.tipo === 1 ? "visual" : "movilidad"})` };
} else if (origen === "se_va") {
    st.enParada = false;
    traza = { payload: `D${String(ID).padStart(2, "0")} se va de ${PARADA}` };
} else if (origen === "tick" && ahora - st.ultima >= PERIODO_MS) {
    st.ultima = ahora;
    st.n += 1;
    if (st.enParada) {
        // service data: versión, tipo de asistencia e id en 16 bits
        const buf = Buffer.from([1, st.tipo, (ID >> 8) & 0xff, ID & 0xff]);
        anuncio = { topic: `${P}/sim/ble/${PARADA}`, payload: buf, qos: 0, retain: false };
    }
}
context.set("st", st);

const hex = [1, st.tipo, (ID >> 8) & 0xff, ID & 0xff].map(b => b.toString(16).padStart(2, "0")).join(" ");
node.status(st.enParada
    ? { fill: "green", shape: "dot", text: `en ${PARADA} | baliza n.º ${st.n} [${hex}] cada ${Math.round(PERIODO_MS / 100) / 10} s` }
    : { fill: "grey", shape: "ring", text: `lejos de la parada | baliza n.º ${st.n} [${hex}], nadie la recibe` });

return [anuncio, traza];

// Conecta el panel al broker y se suscribe a todo lo que publican la nube,
// la parada y el autobús. El panel solo escucha: no publica nada.
const P = env.get("TOPIC_PREFIX");
const ID = env.get("PARADA_ID");
node.send([{ action: "connect", broker: {
    broker: env.get("MQTT_BROKER"), port: Number(env.get("MQTT_PORT")),
    clientid: "", cleansession: true, force: true
} }, null]);
node.send([{ action: "subscribe", topic: [
    `${P}/parada/${ID}/+`, `${P}/autobus/+/asistencia`, `${P}/autobus/+/orden`, `${P}/autobus/+/evento`
].map(t => ({ topic: t, qos: 1 })) }, null]);
node.send([null, { origen: "arranque" }]);
node.status({ fill: "blue", shape: "ring", text: `escucha ${P}/parada/${ID}/+ y ${P}/autobus/+/...` });
return null;

// MODELO DEL PANEL.
// Reconstruye el estado del sistema solo con lo que se oye por MQTT y lo reparte
// a los widgets. No usa nada de las demás pestañas.
// Salidas: 1 solicitud, 2 último aviso, 3 ultrasonidos, 4 próximos (texto),
// 5 galga, 6 gráfica de minutos, 7 gráfica de estado, 8 gráfica de cierres,
// 9 tabla de autobuses, 10 tabla de mensajes.
const P = env.get("TOPIC_PREFIX");
const F = Number(env.get("FACTOR_TIEMPO")) || 1;
const ID = env.get("PARADA_ID");
const BUSES = String(env.get("BUSES") || "").split(",").map(x => x.trim()).filter(Boolean);
const arranque = msg.origen === "arranque";
const out = new Array(10).fill(null);

const RESULTADOS = ["Con el pulsador", "Al irse el autobús"];
const NIVEL = { enviada: 1, asignada: 1, "en parada": 2 };

let st = flow.get("panel");
if (!st || arranque) {
    st = { solicitud: null, aviso: "ninguno", vehiculo: "calzada libre",
        proximos: null, buses: {}, eventos: [], resultados: {}, enviado: {} };
    RESULTADOS.forEach(r => { st.resultados[r] = 0; });
    BUSES.forEach(b => { st.buses[b] = { lcd: "", actuador: "en reposo" }; });
}
function evento(origen, texto) {
    const d = new Date();
    const hora = [d.getHours(), d.getMinutes(), d.getSeconds()].map(x => String(x).padStart(2, "0")).join(":");
    st.eventos.unshift({ Hora: hora, Origen: origen, Mensaje: texto });
    if (st.eventos.length > 12) st.eventos.pop();
}

let nuevaLista = false;
if (!arranque && typeof msg.topic === "string" && msg.topic.startsWith(P + "/")) {
    const [clase, id, tema] = msg.topic.slice(P.length + 1).split("/");
    const p = msg.payload;
    const obj = p && typeof p === "object" && !Buffer.isBuffer(p);

    if (clase === "parada" && id === ID) {
        if (tema === "solicitud" && obj) {
            st.solicitud = { id: p.solicitud, linea: p.linea, estado: "enviada", pulsador: false };
            evento(ID, `Solicitud de la línea ${p.linea} (${p.asistencia})`);
        } else if (tema === "deteccion" && obj) {
            st.vehiculo = p.estado === "detenido" ? `detenido a ${p.distancia_cm} cm` : "calzada libre";
            evento(ID, p.estado === "detenido" ? `Vehículo detenido a ${p.distancia_cm} cm` : "El vehículo se va");
        } else if (tema === "proximos") {
            // Igual que la parada: una lista retenida de una ejecución anterior no vale
            const reciente = obj && Array.isArray(p.buses) && (Date.now() / 1000 - p.ts) <= 60 / F + 3;
            st.proximos = reciente ? p.buses : null;
            nuevaLista = reciente;
        } else if (tema === "aviso" && obj) {
            const mia = st.solicitud && p.solicitud === st.solicitud.id;
            if (p.tipo === "asignado") { if (mia) st.solicitud.estado = "asignada"; st.aviso = `Línea ${p.linea} avisada`; }
            else if (p.tipo === "llegado") { if (mia) st.solicitud.estado = "en parada"; st.aviso = `El autobús de la línea ${p.linea} ha llegado`; }
            else if (p.tipo === "cerrada") {
                st.resultados[RESULTADOS[mia && st.solicitud.pulsador ? 0 : 1]] += 1;
                if (mia) st.solicitud = null;
                st.aviso = `Solicitud de la línea ${p.linea} cerrada`;
            }
            evento("Nube", `Aviso ${p.tipo}: línea ${p.linea}`);
        }
    } else if (clase === "autobus") {
        if (tema === "asistencia") {
            if (obj && p.solicitud) {
                if (!st.buses[id]) st.buses[id] = { lcd: "", actuador: "en reposo" };
                st.buses[id].lcd = `${p.parada} ${p.linea} / ${p.asistencia === "movilidad" ? "RAMPA" : "VISUAL"}`;
                evento("Nube", `Asignación a ${id}: ${p.parada} ${p.linea}`);
            } else if (st.buses[id]) {
                st.buses[id].lcd = "";
                st.buses[id].actuador = "en reposo";
            }
        } else if (tema === "orden" && obj && st.buses[id]) {
            st.buses[id].actuador = p.tipo === "guiar" ? "zumbador sonando" : (p.tipo === "rampa" ? "rampa desplegada" : "en reposo");
            evento("Nube", `Orden ${p.tipo} a ${id}`);
        } else if (tema === "evento" && obj && p.tipo === "recogido") {
            if (st.buses[id]) st.buses[id].actuador = "en reposo";
            if (st.solicitud && st.solicitud.id === p.solicitud) st.solicitud.pulsador = true;
            evento(id, "El conductor confirma la recogida");
        }
    }
}

// ---------- reparto a los widgets (solo lo que cambia) ----------
function texto(i, clave, valor) {
    if (arranque || st.enviado[clave] !== valor) { st.enviado[clave] = valor; out[i] = { payload: valor }; }
}
texto(0, "solicitud", st.solicitud ? `línea ${st.solicitud.linea}, ${st.solicitud.estado}` : "ninguna");
texto(1, "aviso", st.aviso);
texto(2, "vehiculo", st.vehiculo);
texto(3, "proximos", st.proximos === null ? "sin datos"
    : (st.proximos.length ? st.proximos.map(b => `${b.linea} ${b.min} min`).join(", ") : "ninguno en 20 min"));

if (arranque) {
    out[5] = { payload: [] };   // vacía las gráficas de líneas
    out[6] = { payload: [] };
} else if (nuevaLista && st.proximos) {
    // Con cada renovación de la lista (30 s de escenario) se añade un punto a las gráficas
    if (st.proximos.length) out[4] = { payload: st.proximos[0].min };
    const lineas = [];
    for (const b of st.proximos) {
        if (!lineas.some(x => x.topic === b.linea)) lineas.push({ topic: b.linea, payload: b.min });
    }
    if (lineas.length) out[5] = lineas;
    out[6] = { topic: "Solicitud", payload: st.solicitud ? (NIVEL[st.solicitud.estado] || 1) : 0 };
}
const resumen = JSON.stringify(st.resultados);
if (arranque || st.enviado.resultados !== resumen) {
    st.enviado.resultados = resumen;
    out[7] = { payload: RESULTADOS.map(r => ({ resultado: r, n: st.resultados[r] })) };
}
const filas = Object.keys(st.buses).sort().map(b => ({
    "Autobús": b, "LCD": st.buses[b].lcd || "(en blanco)", "Zumbador y rampa": st.buses[b].actuador }));
const tablaBuses = JSON.stringify(filas);
if (arranque || st.enviado.buses !== tablaBuses) { st.enviado.buses = tablaBuses; out[8] = { payload: filas }; }
const tablaEventos = JSON.stringify(st.eventos);
if (arranque || st.enviado.eventos !== tablaEventos) { st.enviado.eventos = tablaEventos; out[9] = { payload: st.eventos.slice() }; }

flow.set("panel", st);
node.status({ fill: "blue", shape: "dot", text: st.solicitud ? `solicitud ${st.solicitud.linea}: ${st.solicitud.estado}` : "sin solicitud" });
return out;
